import axios from 'axios';
import constants from '../../config/constants';
import { updateTransportAreaService } from './transportFee';

// Plain (non-thunk) axios calls - the Transport page (views/admin/Transport) keeps its own local
// state, same as Inventory, so none of this needs a redux slice. Routes (fee structures), their
// stops and student assignment already live in actions/admin/transportFee.js, which the Routes
// tab reuses as-is.
const BASE = constants.API_BASE_URL;

const APIS = {
  bus: '/api/bus', // POST, PUT /{id}, GET /school/{schoolId}, DELETE /{id}
  driver: '/api/admin', // create-driver, get-all-drivers/{schoolId}, update-driver/{id}, delete-driver/{id}
  busDriver: '/api/bus-driver', // POST /select-route, GET /current-route
  studentTransport: '/api/student-transport', // GET /school/{schoolId}/batch/{batchId}
};

// -------------------- Buses -------------------- //

export const fetchBusesApi = data =>
  axios.get(`${BASE}${APIS.bus}/school/${data.schoolId}`, constants.setHeader(data.token));

export const saveBusApi = data => axios.post(`${BASE}${APIS.bus}`, data.postData, constants.setHeader(data.token));

export const updateBusApi = data =>
  axios.put(`${BASE}${APIS.bus}/${data.busId}`, data.postData, constants.setHeader(data.token));

export const deleteBusApi = data => axios.delete(`${BASE}${APIS.bus}/${data.busId}`, constants.setHeader(data.token));

// -------------------- Drivers -------------------- //
// The backend's own driver endpoints: create-driver makes the employee (profession DRIVING) and a
// ROLE_DRIVER login in one go; get-all-drivers lists by that profession.

export const DRIVER_DESIGNATION = 'Driver';
export const DRIVER_DEPARTMENT = 'Transport';

export const fetchDriversApi = async data => {
  const res = await axios.get(
    `${BASE}${APIS.driver}/get-all-drivers/${data.schoolId}`,
    constants.setHeader(data.token)
  );
  return res.data || [];
};

export const saveDriverApi = data =>
  axios.post(`${BASE}${APIS.driver}/create-driver`, data.postData, constants.setHeader(data.token));

export const updateDriverApi = data =>
  axios.put(`${BASE}${APIS.driver}/update-driver/${data.employeeId}`, data.postData, constants.setHeader(data.token));

export const deleteDriverApi = data =>
  axios.delete(`${BASE}${APIS.driver}/delete-driver/${data.employeeId}`, constants.setHeader(data.token));

// -------------------- Driver <-> bus <-> route -------------------- //
// The backend keeps one assignment per driver per batch and has no list-all endpoint: select-route upserts it
// (so assigning again replaces it), current-route reads one driver's, and unassign-route deletes it by its id.

export const selectRouteApi = data =>
  axios.post(`${BASE}${APIS.busDriver}/select-route`, data.postData, constants.setHeader(data.token));

// Removes one driver's bus and route assignment. The driver, the bus and the route themselves stay.
export const unassignRouteApi = data =>
  axios.delete(
    `${BASE}${APIS.busDriver}/unassign-route/${data.driverRouteAssignmentId}`,
    constants.setHeader(data.token)
  );

// Resolves to null (not an error) when the driver has no route yet - that case comes back from the
// backend as a 500 "Driver has not selected any route".
export const fetchCurrentRouteApi = async data => {
  try {
    const res = await axios.get(
      `${BASE}${APIS.busDriver}/current-route${constants.makeParams({
        employeeId: data.employeeId,
        schoolId: data.schoolId,
        batchId: data.batchId,
      })}`,
      constants.setHeader(data.token)
    );
    return res.data || null;
  } catch (err) {
    return null;
  }
};

// Every driver's assignment for a batch. The backend has no list-all, so this asks once per driver.
export const fetchDriverAssignments = async ({ drivers, schoolId, batchId, token }) => {
  if (!batchId) return [];
  const rows = await Promise.all(
    drivers.map(driver => fetchCurrentRouteApi({ employeeId: driver.employeeId, schoolId, batchId, token }))
  );
  return rows.filter(Boolean);
};

// A live read (not a page's already-loaded copy), for checks right before a delete: assignments are made
// from several places and by other admins, so a cached list can be out of date.
export const fetchSchoolAssignments = async ({ schoolId, batchId, token }) => {
  const drivers = await fetchDriversApi({ schoolId, token });
  return fetchDriverAssignments({ drivers, schoolId, batchId, token });
};

// -------------------- Route <-> stop name -------------------- //

// The backend finds a driver's students by matching the stops' `ruteName` against the assignment's
// route name as exact text (it never checks either against the route itself). A stop saved under any
// other name - older data, or another screen - is therefore silently missing for the driver. Every stop
// written from this UI already carries its route's name; this rewrites the ones that don't. Resolves to
// how many stops were changed.
export const syncRouteStopNames = async ({ route, areas, token }) => {
  const stale = (areas || []).filter(area => area.ruteName !== route.description);
  await Promise.all(
    stale.map(area => updateTransportAreaService({ token, postData: { ...area, ruteName: route.description } })())
  );
  return stale.length;
};

// -------------------- Students on routes -------------------- //

export const fetchSchoolBatchStudentTransportApi = data =>
  axios.get(
    `${BASE}${APIS.studentTransport}/school/${data.schoolId}/batch/${data.batchId}`,
    constants.setHeader(data.token)
  );

