// -------------------- Admin: mark bus attendance -------------------- //
// The attendance endpoints take the driver's employeeId, so an admin marks for a bus through the driver assigned to it.

// The students of the route a driver is assigned to, each with the status already marked for that day and trip.
export const fetchRouteStudentsApi = data =>
  axios.get(
    `${BASE}${ATTENDANCE_API}/route-students${constants.makeParams({
      employeeId: data.employeeId,
      schoolId: data.schoolId,
      batchId: data.batchId,
      tripType: data.tripType,
      date: data.date,
    })}`,
    constants.setHeader(data.token)
  );

// students: [{ studentId, status: 'PICKED' | 'DROPPED' | 'ABSENT' }]
export const markBusAttendanceApi = data =>
  axios.post(`${BASE}${ATTENDANCE_API}/mark`, data.postData, constants.setHeader(data.token));

// -> { schoolId, batchId, totalTransportStudents, routes: [{ transportFeeStructId, routeName, studentCount }] }
export const fetchTransportStudentCountApi = async ({ schoolId, batchId, token }) => {
  const res = await axios.get(
    `${BASE}${APIS.studentTransport}/student/count${constants.makeParams({ schoolId, batchId })}`,
    constants.setHeader(token)
  );
  return res.data;
};

// GET /api/reports/transport/route/{routeId}?batchId=&pendingOnly= (routeId = the route's transportFeeStructId) -> one row per
// student on the route: monthly fee, paid, balance, what is due so far, paid / pending months and the guardian's contact
// (paymentStatus PAID | DUE | UP_TO_DATE).
export const fetchTransportFeeReportApi = ({ routeId, batchId, pendingOnly = false, token }) =>
  axios.get(
    `${constants.API_BASE_URL}/api/reports/transport/route/${routeId}${constants.makeParams({ batchId, pendingOnly })}`,
    constants.setHeader(token)
  );
