// The public Scholae landing page (marketing, pricing, demo form) is only for Scholae's own address. On any other domain,
// such as a school's own site (tanacademy.in), "/" goes straight to the login page instead.
// To show the landing page on one more address, add its hostname here (without "www.").
const LANDING_HOSTS = ['scholae.innobs.com', 'localhost', '127.0.0.1'];
export const LANDING_SITE_URL = 'https://scholae.innobs.com';
export const isLandingHost = () => LANDING_HOSTS.includes(window.location.hostname.replace(/^www\./, ''));

export const getDomainContent = () => {
  const hostname = window.location.hostname.replace(/^www\./, '');
  return domainContent[hostname] || defaultContent;
};

export default domainContent;
