export const getCurrentYearBatchUtils = () => {
  const currentYr = new Date().getFullYear();
  const currentMonth = new Date().getMonth();
  const startYear = currentMonth > 5 ? currentYr : currentYr - 1;
  return {
    startYear,
    endYear: startYear + 1,
  };
};

// The next 5 academic-year ranges available to clone into, starting right after the
// latest existing batch's end year (or the current year if there are no batches yet).
// Used by CloneBatch for its "clone to" picker.
export const makeCloneYearOptions = ({ batchList, cloneBatchList }) => {
  const { startYear } = getCurrentYearBatchUtils();
  const maxYearFromBatch = batchList?.length ? Math.max(...batchList.map(el => el.endYear)) : startYear + 1;
  return new Array(5)
    .fill(maxYearFromBatch)
    .map((item, i) => ({
      label: `${item + i} - ${item + i + 1}`,
      value: item + i,
      startYear: item + i,
      endYear: item + i + 1,
    }))
    .filter(el => !cloneBatchList?.map(cto => cto?.startYear).includes(el?.startYear));
};

