export const isActualCurrentBatchOrHigher = () => {
  const currBt = getGlobalCurrentBatchUtils();
  const actCurrBt = getGlobalCurrentBatchUtils('actualCurrentBatch');
  return currBt?.batchId >= actCurrBt?.batchId;
};

