export const handleKeyNumberPress = event => {
  const regex = new RegExp('^[0-9+]*$');
  const key = String.fromCharCode(event.charCode ? event.which : event.charCode);
  if (regex.test(key)) {
    return true;
  }
  return false;
};

export const handleKeyCharacterPress = event => {
  const regex = new RegExp('^[a-zA-Z0-9.]+$');
  const key = String.fromCharCode(event.charCode ? event.which : event.charCode);
  if (regex.test(key)) {
    return true;
  }
  return false;
};

// Teacher/student names are often stored in ALL CAPS (a common convention for official records),
// which reads fine in a formal document but is hard to scan in a dropdown list next to normal
// prose. Title-cases each word while leaving separators (spaces, the "." in an initial like
// "KANNAN.K") alone, so "KANNAN.K" -> "Kannan.K" rather than lowercasing the initial too.
export const toTitleCase = str => {
  if (!str || typeof str !== 'string') return str;
  return str.toLowerCase().replace(/\b\w+/g, word => word.charAt(0).toUpperCase() + word.slice(1));
};

export const makeSubstring = (data, length) => {
  return data?.length > length ? `${data.substring(0, length)}...` : data;
};

