export const convertXlsxToJson = (file, setExcelJson) => {
  const reader = new FileReader();

  reader.onload = event => {
    try {
      const data = new Uint8Array(event.target.result);
      const workbook = XLSX.read(data, { type: 'array' });

      const firstSheetName = workbook.SheetNames[0];
      const worksheet = workbook.Sheets[firstSheetName];

      const rows = XLSX.utils.sheet_to_json(worksheet, {
        header: 1,
        defval: '',
      });

      const list = rows.slice(1);
      const res = extractSubCodes(list);

      setExcelJson(res);
    } catch (err) {
      console.error(err);
      setExcelJson([]);
    }
  };

  reader.onerror = err => {
    console.error(err);
    setExcelJson([]);
  };

  reader.readAsArrayBuffer(file);
};

export const validateExcelJsonList = (li, message) => {
  const isInvalid = li.some(el => {
    return el.some(el1 => !el1);
  });
  if (isInvalid) {
    return (
      message ||
      'Either few subject columns are empty or Some additional empty columns are added, Please upload valid file'
    );
  } else {
    return '';
  }
};

export const validateSubCodesExist = (li, subjectCodes) => {
  const subCodeList = subjectCodes.map(el => el?.code);
  let subCode = '';
  const codeNotExist = li.some(el => {
    return el.some(el1 => {
      if (!subCodeList?.includes(el1)) {
        subCode = el1;
        return true;
      }
    });
  });
  if (codeNotExist) {
    return `${!subCode ? `Few ` : ''} Subject code${
      subCode ? ` [ ${subCode} ]` : ''
    } is not match with configured subjects. Please upload valid file`;
  } else {
    return '';
  }
};

export const convertModuleToName = module => {
  const mName = module?.replace(/_MODULE$/, '');
  const undReplace = mName?.replace(/_/g, ' ');
  return undReplace
    ?.split(' ')
    ?.map(el => makeFirstCaps(el))
    ?.join(' ');
};

