// Binary search to find the next highest id for id: time complexity of O(log n)
export function findNextHighestNumber(arr, targetParamName, targetParamValue) {
  let left = 0;
  let right = arr.length - 1;
  let mid;

  while (left <= right) {
    mid = Math.floor((left + right) / 2);

    if (arr?.[mid]?.[targetParamName] === targetParamValue) {
      // If the target parameter value is found in the array, return the next object's parameter value
      return arr?.[mid + 1] ? arr?.[mid + 1]?.[targetParamName] : null;
    } else if (arr?.[mid]?.[targetParamName] < targetParamValue) {
      // If the middle object's parameter value is less than the target, search the right half of the array
      left = mid + 1;
    } else {
      // If the middle object's parameter value is greater than the target, search the left half of the array
      right = mid - 1;
    }
  }

  // If the target parameter value is not found in the array, return the first object's parameter value
  return arr?.[0]?.[targetParamName];
}

export function findPreviousSmallerNumber(arr, targetParamName, targetParamValue) {
  let left = 0;
  let right = arr.length - 1;
  let mid;

  while (left <= right) {
    mid = Math.floor((left + right) / 2);

    if (arr?.[mid]?.[targetParamName] === targetParamValue) {
      // If the target parameter value is found in the array, return the previous object's parameter value
      return arr?.[mid - 1] ? arr?.[mid - 1]?.[targetParamName] : null;
    } else if (arr?.[mid]?.[targetParamName] < targetParamValue) {
      // If the middle object's parameter value is less than the target, search the right half of the array
      left = mid + 1;
    } else {
      // If the middle object's parameter value is greater than the target, search the left half of the array
      right = mid - 1;
    }
  }

  // If the target parameter value is not found in the array, return the last object's parameter value
  return arr?.[arr.length - 1]?.[targetParamName];
}

