export function getGroupedOptions(list, passModule) {
  const moduleWiseGroupName = {
    employeeSubjects: { group: 'course.name', optionFormDb: item => getEmployeeSubjectOptionForm(item) },
  };

  const propertyNames = moduleWiseGroupName?.[passModule]?.group?.split('.');

  const groupedOptions = [];

  list.forEach(item => {
    const courseName = item?.[propertyNames[0]]?.[propertyNames[1]];
    const option = moduleWiseGroupName?.[passModule]?.optionFormDb?.(item);

    // Check if a group already exists for this course name
    const groupIndex = groupedOptions?.findIndex(group => group.label === courseName);

    // If the group doesn't exist, create it
    if (groupIndex === -1) {
      groupedOptions.push({
        label: courseName,
        options: [option],
      });
    } else {
      // If the group exists, add the option to its options array
      groupedOptions[groupIndex].options.push(option);
    }
  });

  return groupedOptions;
}

export function deepEqual(object1, object2) {
  if (object1 === object2) {
    return true;
  }

  if (typeof object1 != 'object' || typeof object2 != 'object' || object1 == null || object2 == null) {
    return false;
  }

  const keys1 = Object.keys(object1);
  const keys2 = Object.keys(object2);

  if (keys1.length !== keys2.length) {
    return false;
  }

  for (const key of keys1) {
    if (!keys2.includes(key) || !deepEqual(object1[key], object2[key])) {
      return false;
    }
  }

  return true;
}

export function arraysEqual(arr1, arr2) {
  if (arr1.length !== arr2.length) {
    return false;
  }

  for (let i = 0; i < arr1.length; i++) {
    if (!deepEqual(arr1[i], arr2[i])) {
      return false;
    }
  }

  return true;
}

// Login names are stored as emails. A bare name (no "@") gets "@gmail.com" added, exactly like the login
// page does, so users can be created and signed in by a short unique username. Empty values and anything
// that already contains "@" are returned unchanged.
export const toLoginEmail = value => {
  const trimmed = String(value || '').trim();
  if (!trimmed || trimmed.includes('@')) return trimmed;
  return `${trimmed}@gmail.com`;
};
