export const USER_LOGGED_IN = 'ADMIN_LOGGED_IN';
export const USER_LOGGED_OUT = 'USER_LOGGED_OUT';

export const SHOW_TOAST = 'SHOW_TOAST';
export const CLOSE_TOAST = 'CLOSE_TOAST';

export const GET_USER_PROFILE = 'GET_USER_PROFILE';

export const SET_ACTIVE_TAB = 'SET_ACTIVE_TAB';
export const SET_VISITED_COURSE_ID = 'SET_VISITED_COURSE_ID';

// Common
export const SET_COMMON_STORE_PARAM = 'SET_COMMON_STORE_PARAM';
export const SET_FEATURE_FLAGS = 'SET_FEATURE_FLAGS';

// Notification system
export const showToast = (message, errorType) => {
  return {
    type: SHOW_TOAST,
    message,
    errorType,
  };
};

export const closeToast = () => ({
  type: CLOSE_TOAST,
});

//= ========== Reducer call functions begin ===========//
export const userLoggedIn = user => ({
  type: USER_LOGGED_IN,
  user,
});

// Per-user feature switches read from the backend (see actions/admin/featureFlags.js): { CONFIG_NAME: value }.
export const setFeatureFlags = flags => ({
  type: SET_FEATURE_FLAGS,
  flags,
});

export const userLoggedOut = () => ({
  type: USER_LOGGED_OUT,
});

export const getUserProfile = userProfile => ({
  type: GET_USER_PROFILE,
  userProfile,
});

// Active tab and tab courseId
export const setStoreActiveTab = activeTab => {
  return {
    type: SET_ACTIVE_TAB,
    activeTab,
  };
};

export const setVisitedCourseId = visitData => {
  return {
    type: SET_VISITED_COURSE_ID,
    activeTab: visitData.activeTab,
    courseId: visitData.courseId,
  };
};

export const setCommonParam = (paramName, value) => {
  store.dispatch({
    type: SET_COMMON_STORE_PARAM,
    paramName,
    value,
  });
};
//= ========== Reducer call functions begin ===========//

