export const login = credentials => async dispatch => {
  const res = await axios.post(`${constants.API_BASE_URL}/api/auth/signin`, credentials);
  // Guardians (parents) use the mobile app, not this web dashboard - SA is kept allowed
  // since it's used here for multi-school switching/management.
  const webAllowedRoles = [constants.roles.admin, constants.roles.teacher, constants.roles.SA];
  if (!webAllowedRoles.includes(res.data?.userRole)) {
    throw { response: { data: { message: MSG.login_role_not_allowed } } };
  }
  setLoggedUserUtils({ ...res.data });
  dispatch(userLoggedIn(res.data));
  // const prismic = await PrismicClient.query('', { pageSize: 100 });
  // console.error({prismic});
  return res.data;
};

export const logout = () => dispatch => {
  dispatch(userLoggedOut());
  localStorage.clear();
};

