export const fetchUserService = data => async dispatch => {
  let url = '';
  if (data.userRole === constants.roles.teacher) {
    url = `/api/employee/get-employee/${data.userId}`;
  } else if (data.userRole === constants.roles.admin) {
    url = `/api/admin/get-school-admin/${data.userId}`;
  }
  try {
    const res = await axios.get(constants.API_BASE_URL + url, constants.setHeader(data.token));
    dispatch(getUserProfile(res.data));
  } catch (err) {
    console.error('Err-fetchUserService', err?.response);
  }
};

export const updateUserService = data => async () => {
  let url = '';
  if (data.userRole === constants.roles.teacher) {
    url = `/api/employee/update-employee/${data.userId}`;
  } else if (data.userRole === constants.roles.admin) {
    url = `/api/admin/update-school-admin/${data.userId}`;
  }
  try {
    await axios.put(constants.API_BASE_URL + url, data.postData, constants.setHeader(data.token));
  } catch (err) {
    console.error('Err-updateUserService', err?.response);
  }
};

export const updatePasswordService = data => () => {
  return axios.post(
    `${constants.API_BASE_URL}/api/auth/change-password`,
    data.passwordData,
    constants.setHeader(data.token)
  );
};

