export const fetchAllSchoolsService = data => async dispatch => {
  try {
    const res = await axios.get(
      `${constants.API_BASE_URL}/api/admin/all-school-by-page${constants.makeParams(data.pageParams)}`,
      constants.setHeader(data.token)
    );
    if (res?.data?.content?.length) {
      setGlobalSchoolUtils(res?.data?.content?.[0]);
    }
    dispatch(getAllSchools(res.data));
    return res.data;
  } catch (err) {
    console.error('fetchAllSchoolsService', err?.response);
  }
};

export const saveSchoolService = data => () => {
  return axios.post(
    `${constants.API_BASE_URL}/api/admin/create-school`,
    data.postData,
    constants.setHeader(data.token)
  );
};

export const fetchSchoolService = data => async dispatch => {
  try {
    const res = await axios.get(
      `${constants.API_BASE_URL}/api/admin/get-school/${data.schoolId}`,
      constants.setHeader(data.token)
    );
    dispatch(getSchool(res.data));
    res?.data?.schoolId && setGlobalSchoolUtils(res?.data);
    return res.data;
  } catch (err) {
    logoutHandler(err);
    return err;
  }
};

