// Create || Update
export const addOrUpdateAppreciationTemplateService = data => {
  const { token, appreciation, schoolId, action, appreTemplateId: passAppreTemplateId } = data;
  const appreTemplateId = appreciation?.appreTemplateId || passAppreTemplateId || 0;
  const url =
    action === 'create'
      ? `/api/user/appreciation-template/${schoolId}`
      : `/api/user/appreciation-template/${schoolId}/${appreTemplateId}`;
  return axios[action === 'create' ? 'post' : 'put'](
    `${constants.API_BASE_URL}${url}`,
    {
      schoolId,
      templateJson: action === 'create' ? appreciation : JSON.stringify(appreciation),
      toWhom: appreciation?.toWhom,
      appreTemplateId,
    },
    constants.setHeader(token)
  );
};

