import axios from 'axios';
import constants from '../../config/constants';

export const GET_ALL_EMPLOYEES = 'GET_ALL_EMPLOYEES';
export const GET_SCHOOL_EMPLOYEES = 'GET_SCHOOL_EMPLOYEES';
export const GET_EMPLOYEE = 'GET_EMPLOYEE';
export const GET_ALL_EMP_ASSIGN_SUBJECTS = 'GET_ALL_EMP_ASSIGN_SUBJECTS';
export const GET_EMP_ASSIGN_SUBJECTS = 'GET_EMP_ASSIGN_SUBJECTS';
// Leave
export const GET_EMPLOYEE_LEAVES = 'GET_EMPLOYEE_LEAVES';

export const UPDATE_EMPLOYEE_ID = 'UPDATE_EMPLOYEE_ID';
export const UPDATE_COURSE_ID = 'UPDATE_COURSE_ID';

// Common
export const updateEmployeeId = employeeId => ({
  type: UPDATE_EMPLOYEE_ID,
  employeeId,
});

export const updateCourseId = courseId => ({
  type: UPDATE_COURSE_ID,
  courseId,
});

//= ========== Reducer call functions begin ===========//
export const getAllEmployees = employeesData => ({
  type: GET_ALL_EMPLOYEES,
  employeesData,
});

export const getSchoolEmployees = employees => ({
  type: GET_SCHOOL_EMPLOYEES,
  employees,
});

export const getEmployee = employee => ({
  type: GET_EMPLOYEE,
  employee,
});

export const getAllEmpAssignSubjects = empAssignSubjects => ({
  type: GET_ALL_EMP_ASSIGN_SUBJECTS,
  empAssignSubjects,
});

export const getEmpAssignSubject = empAssignSubject => ({
  type: GET_EMP_ASSIGN_SUBJECTS,
  empAssignSubject,
});

// Leave
export const getEmployeeLeaves = empLeaves => ({
  type: GET_EMPLOYEE_LEAVES,
  empLeaves,
});
//= ========== Reducer call functions begin ===========//

//= ========== User routing begin ===========//
export const fetchAllEmployeesService = data => async dispatch => {
  try {
    const res = await axios.get(
      `${constants.API_BASE_URL}/api/admin/get-school-employees-by-page/${data.schoolId}${constants.makeParams(
        data.pageParams
      )}`,
      constants.setHeader(data.token)
    );
    dispatch(getAllEmployees(res.data));
    return res.data;
  } catch (err) {
    console.error(err.response);
  }
};

// profession ('TEACHING' | 'NON_TEACHING') filters server-side via this same endpoint's own
// query param - the BE already does the TEACHING/NON_TEACHING split correctly; a client-side
// text-matching guess on top of it was never necessary and broke down against real data where
// designation text doesn't reliably say "teach". Every Teacher/Worker consumer (Staff Attendance,
// Worker Salary Impact, School Staffs) fetches through here now instead of filtering afterward.
export const fetchSchoolEmployeesApi = async data => {
  try {
    const res = await axios.get(
      `${constants.API_BASE_URL}/api/admin/get-school-employees/${data.schoolId}${constants.makeParams(
        data.profession ? { profession: data.profession } : null
      )}`,
      constants.setHeader(data.token)
    );
    return res.data;
  } catch (err) {
    console.error(err.response);
  }
};

export const fetchSchoolEmployeesService = data => async dispatch => {
  try {
    const employees = await fetchSchoolEmployeesApi(data);
    dispatch(getSchoolEmployees(employees));
    return employees;
  } catch (err) {
    console.error(err.response);
  }
};

