// Leave types of a school (casual, sick...) with the days a teacher gets a year, which a teacher picks from when applying.
export const fetchLeaveTypesApi = async data => {
  const res = await axios.get(
    `${constants.API_BASE_URL}/api/all-employee-leave-type/${data.schoolId}`,
    constants.setHeader(data.token)
  );
  return res.data || [];
};

export const saveLeaveTypeApi = data => {
  const body = { leaveType: data.leaveType, totalLeaves: data.totalLeaves };
  return data.leaveTypeId
    ? axios.put(
        `${constants.API_BASE_URL}/api/employee-leave-type/${data.schoolId}/${data.leaveTypeId}`,
        body,
        constants.setHeader(data.token)
      )
    : axios.post(
        `${constants.API_BASE_URL}/api/employee-leave-type/${data.schoolId}`,
        body,
        constants.setHeader(data.token)
      );
};

export const deleteLeaveTypeApi = data =>
  axios.delete(
    `${constants.API_BASE_URL}/api/employee-leave-type/${data.leaveTypeId}`,
    constants.setHeader(data.token)
  );
