// The old School page had one tab each for batches, classes, subjects and teacher subjects; each is a sidebar page now,
// and old links (?subjects, ?teacher-subjects ...) land on the page that tab became.
const SchoolLegacyRedirect = ({ location }) => {
  const search = location?.search || '';
  // Longest name first: "teacher-subjects" also contains "subjects".
  if (search.includes('teacher-subjects')) {
    return <Redirect to="/admin/subjects?tab=teacher-subjects" />;
  }
  const target = search.includes('subjects') ? 'subjects' : search.includes('courses') ? 'courses' : 'batches';
  return <Redirect to={`/admin/${target}`} />;
};
