import axios from 'axios';
import constants from 'config/constants';
import { store } from 'index';
import { getGlobalCurrentBatchUtils } from 'utils/commonFunc';

const APIS = {
  updateGroup: '/api/admin/fee-group', // /${schoolId}
  getAllGroup: `/api/admin/fee-group`, // /{schoolId}
  updateFeeStructure: `/api/admin/fee-structure`, // /{schoolId}/{batchId}/{feeGroupId}
  getAllFeeStructureByGroupId: `/api/admin/fee-structure-by-group-id`, // /{schoolId}/{batchId}/{feeGroupId}
  updateFeeGroupToCourse: `/api/admin/assign-fee-group-to-course`, // /{schoolId}/{batchId}
  getAllCoursesForGroup: `/api/admin/assign-fee-group-to-course`, // /{schoolId}/{batchId}
  // This endpoint used to assign a student to a whole fee GROUP; the backend repurposed the
  // same table/URL to link a student directly to one fee-structure line instead (feeGroupId
  // column -> feeStructId), so it now needs a feeStructId in the PUT body and on the GET path.
  updateFeeStructureToStudent: `/api/admin/assign-fee-group-to-students`, //{schoolId}/{batchId} (PUT) or /{studFeeStrId} (DELETE)
  getAllStudentsForFeeStructure: `/api/admin/assign-fee-group-to-students`, ///{schoolId}/{batchId}/{feeStructId}
  // The assignment DTO above only returns bare name fields, so enrich with this existing
  // single-student lookup (already used elsewhere in the app) for email/registerNumber/class.
  studentDetail: `/api/student`, // /{studentId}/{batchId}
  getAllFeeStructureForCourse: `/api/admin/fee-structure-by-course-id`, // /{schoolId}/{batchId}/{courseId}
  updateStudentPayment: `/api/admin/student-payment`, // /{schoolId}/{studentId}
  getStudentPayments: `/api/admin/student-payment-history`, // /{schoolId}/{batchId}/{studentId}/{courseId}
  deleteFeeGroup: `/api/admin/fee-group`, // /{feeGroupId}
  deleteFeeStructure: `/api/admin/fee-structure`, // /{feeStructId}
  adjustStudentFee: `/api/admin/adjust-student-fee`, // /{schoolId}/{batchId}/{studentId} (GET, POST) or /{adjustFeeId} (PUT, DELETE)
  getAllAdjustStudentFee: `/api/admin/all-adjust-student-fee`, // /{schoolId}/{batchId}
  createStudentFeeRefund: `/api/admin/student-fee-refunds`, // POST
  studentFeeRefundsByPayment: `/api/admin/student-fee-refunds/payment`, // /{studPaymentId} and /{studPaymentId}/total
  studentFeeRefundsByStudent: `/api/admin/student-fee-refunds/student`, // /{studentId}/batch/{batchId}
};

