export const SET_FEES_COMMON_PARAM = 'SET_FEES_COMMON_PARAM';
export const setFeesCommonParam = (paramName, value) => {
  store.dispatch({
    type: SET_FEES_COMMON_PARAM,
    paramName,
    value,
  });
};

const BASE = constants.API_BASE_URL;

export const addFeeGroupService = data => async () => {
  const { schoolId, token, postData } = data;
  return axios.put(`${BASE}${APIS['updateGroup']}/${schoolId}`, postData, constants.setHeader(token));
};

export const fetchAllFeeGroupService = data => async dispatch => {
  const { schoolId, token } = data;
  try {
    const res = await axios.get(`${BASE}${APIS['getAllGroup']}/${schoolId}`, constants.setHeader(token));
    dispatch(getAllFeeGroups(res.data));
  } catch (err) {
    console.error('err-fetchAllFeeGroupService', err);
  }
};

// Plain (non-thunk) variant of fetchAllFeeGroupService, for read-only spots (e.g. a student's own
// profile) that just need the group list once without wiring up the fees reducer for it.
export const fetchAllFeeGroupPlainService = async (schoolId, token) => {
  const res = await axios.get(`${BASE}${APIS['getAllGroup']}/${schoolId}`, constants.setHeader(token));
  return res.data;
};

export const addFeeStructureService = data => async () => {
  const { batchId = data?.batchId } = getGlobalCurrentBatchUtils();
  const { schoolId, feeGroupId, token, postData } = data;
  return axios.put(
    `${BASE}${APIS['updateFeeStructure']}/${schoolId}/${batchId}/${feeGroupId}`,
    postData,
    constants.setHeader(token)
  );
};

