//* ***************** Attendance ******************//
// "Period 1".."Period 10" is the literal timePeriod text the timetable grid saves (see
// TIMETABLE_PERIODS in TimetableAllocationGrid.jsx). Attendance's per-student record has fixed
// periodOne..periodTen fields to mark present/absent against, so we derive that key here -
// mirrors the mapping the backend used to do server-side in the now-unused class-periords API.
const PERIOD_ORDER = [
  'Period 1',
  'Period 2',
  'Period 3',
  'Period 4',
  'Period 5',
  'Period 6',
  'Period 7',
  'Period 8',
  'Period 9',
  'Period 10',
];
const PERIOD_KEY_BY_LABEL = {
  'Period 1': 'periodOne',
  'Period 2': 'periodTwo',
  'Period 3': 'periodThree',
  'Period 4': 'periodFour',
  'Period 5': 'periodFive',
  'Period 6': 'periodSix',
  'Period 7': 'periodSeven',
  'Period 8': 'periodEight',
  'Period 9': 'periodNine',
  'Period 10': 'periodTen',
};

export const fetchClassPeriodsService = data => async dispatch => {
  try {
    const res = await axios.get(
      `${constants.API_BASE_URL}/api/employee/course-time-table/${data.courseId}/${data.batchId}/${data.schoolId}/${data.day}`,
      constants.setHeader(data.token)
    );
    const classPeriods = [...(res.data || [])]
      .sort((a, b) => PERIOD_ORDER.indexOf(a.timePeriod) - PERIOD_ORDER.indexOf(b.timePeriod))
      .map(item => ({ ...item, period: PERIOD_KEY_BY_LABEL[item.timePeriod] }));
    dispatch(getClassPeriods(classPeriods));
    return classPeriods;
  } catch (err) {
    console.error('err', err);
  }
};

