//* ****************Notice board **************** */
// Newest first, newest creation date on top. Without a date the paged list is read (page 1 replaces the list, later
// pages are added to it); with a date only that day's notices come back (kept for callers that still pass one).
export const sortByCreationDesc = list =>
  [...(list || [])].sort((a, b) => new Date(b.creationDateTime || 0) - new Date(a.creationDateTime || 0));

export const fetchAllNoticeBoardService = data => async (dispatch, getState) => {
  try {
    if (data.date) {
      const res = await axios.get(
        `${constants.API_BASE_URL}/api/common/notice-board/${data.schoolId}/${data.date}`,
        constants.setHeader(data.token)
      );
      dispatch(getAllNoticeBoards(res.data));
      return res;
    }
    const page = data.page || 1;
    const res = await axios.get(
      `${constants.API_BASE_URL}/api/common/notice-board/${data.schoolId}?page=${page}&size=${data.size || 20}`,
      constants.setHeader(data.token)
    );
    const previous = page > 1 ? getState().students.noticeBoardList || [] : [];
    dispatch(getAllNoticeBoards(sortByCreationDesc([...previous, ...(res.data?.content || [])])));
    return res;
  } catch (err) {
    console.error('err-create-notice-board-error', err.response);
  }
};

