// Plain (non-redux, unpaged) - every student of one class in a batch.
export const fetchCourseStudentsListApi = data =>
  axios.get(
    `${constants.API_BASE_URL}/api/employee/course-students/${data.courseId}/${data.batchId}`,
    constants.setHeader(data.token)
  );

// studentId -> { student, className, batchId } for every student of the given batches. No endpoint
// returns a student's class in bulk (and the batch student endpoint caps page size at 50), so this
// walks each batch's classes and their unpaged student lists - a handful of small requests.
export const fetchStudentClassDirectoryApi = async ({ batchIds, token }) => {
  const results = await Promise.all(
    batchIds.map(async batchId => {
      const courses = (await fetchBatchCoursesPlainApi({ batchId, token })).data || [];
      const lists = await Promise.all(
        courses.map(c => fetchCourseStudentsListApi({ courseId: c.courseId, batchId, token }))
      );
      return lists.flatMap((res, idx) =>
        (res.data || []).map(student => [student.studentId, { student, className: courses[idx].name, batchId }])
      );
    })
  );
  return Object.fromEntries(results.flat());
};

// Moves students from one class to another inside one batch (academic year); the backend rejects a
// student who isn't in the "from" class of that batch, a repeated id, or from == to.
export const moveStudentsCourseApi = data =>
  axios.post(
    `${constants.API_BASE_URL}/api/admin/move-students-course`,
    data.postData,
    constants.setHeader(data.token)
  );

// The student's progress in one call (the backend dashboard API): attendance, home work, exam results, parent-note counts and
// appreciation cards for the batch (the student's latest one when no batch is given).
export const fetchStudentProgressApi = async ({ studentId, batchId, token }) => {
  const res = await axios.get(
    `${constants.API_BASE_URL}/api/dashboard/student/${studentId}/progress${constants.makeParams(
      batchId ? { batchId } : null
    )}`,
    constants.setHeader(token)
  );
  return res.data;
};

